import { test } from "node:test";
import assert from "node:assert/strict";

import {
  parsePluginsJs,
  serialisePluginsJs,
  pluginsJsLayout,
  upsertPlugin,
  removePlugin,
} from "../src/core/pluginsfile.js";

const SAMPLE = `// Generated by RPG Maker.
// Do not edit this file directly.
var $plugins =
[
{"name":"A","status":true,"description":"d","parameters":{}},
{"name":"B","status":false,"description":"d","parameters":{"k":"v"}}
];
`;

test("parse finds the array literal", () => {
  const { plugins, start, end } = parsePluginsJs(SAMPLE);
  assert.equal(plugins.length, 2);
  assert.equal(plugins[0].name, "A");
  assert.ok(start > 0 && end > start);
});

test("parse survives brackets and escapes inside strings", () => {
  const source = `var $plugins =\n[\n{"name":"X]y","status":true,"description":"a\\\"b[c","parameters":{}}\n];\n`;
  const { plugins } = parsePluginsJs(source);
  assert.equal(plugins[0].name, "X]y");
  assert.equal(plugins[0].description, 'a"b[c');
});

test("serialise round trips", () => {
  const { plugins } = parsePluginsJs(SAMPLE);
  const text = serialisePluginsJs(plugins);
  assert.ok(text.startsWith("// Generated by RPG Maker.\n"));
  assert.deepEqual(parsePluginsJs(text).plugins, plugins);
});

test("serialise honours the original trailing comma shape", () => {
  // RPG Maker's editor writes "},\n];", several shipped games write "}\n];".
  assert.equal(pluginsJsLayout(SAMPLE).trailingComma, false);
  const withComma = SAMPLE.replace("\n];\n", ",\n];\n");
  assert.equal(pluginsJsLayout(withComma).trailingComma, true);

  const { plugins } = parsePluginsJs(SAMPLE);
  assert.ok(serialisePluginsJs(plugins, { trailingComma: true }).endsWith(",\n];\n"));
  assert.ok(serialisePluginsJs(plugins, { trailingComma: false }).endsWith("\n];\n"));
  // Unknown layout keeps the historical RPG Maker default.
  assert.ok(serialisePluginsJs(plugins).endsWith(",\n];\n"));
});

test("serialise honours CRLF endings", () => {
  const crlf = SAMPLE.replace(/\n/g, "\r\n");
  assert.equal(pluginsJsLayout(crlf).eol, "\r\n");
  assert.equal(pluginsJsLayout(SAMPLE).eol, "\n");

  const { plugins } = parsePluginsJs(crlf);
  const text = serialisePluginsJs(plugins, pluginsJsLayout(crlf));
  assert.ok(text.endsWith("\r\n];\r\n"));
  assert.ok(!/(?<!\r)\n/.test(text), "no bare LF should be left behind");
  assert.deepEqual(parsePluginsJs(text).plugins, plugins);
});

test("parse throws on a missing array", () => {
  assert.throws(() => parsePluginsJs("var nothing = 1;"), /no \$plugins/);
  assert.throws(() => parsePluginsJs("var $plugins = [ {"), /unterminated/);
});

test("upsert adds, enables and leaves alone", () => {
  const { plugins } = parsePluginsJs(SAMPLE);
  assert.equal(upsertPlugin(plugins, { name: "C" }), "added");
  assert.equal(plugins.length, 3);
  assert.equal(upsertPlugin(plugins, { name: "C" }), "unchanged");
  assert.equal(upsertPlugin(plugins, { name: "B" }), "enabled");
  assert.equal(plugins[1].status, true);
});

test("remove deletes the entry", () => {
  const { plugins } = parsePluginsJs(SAMPLE);
  assert.equal(removePlugin(plugins, "A"), true);
  assert.equal(removePlugin(plugins, "A"), false);
  assert.deepEqual(plugins.map((p) => p.name), ["B"]);
});
